const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict'),png=require('./png.cjs');
(async()=>{const url='http://127.0.0.1:8765/api/project?id=character-green-flower-idle-20261027',out=path.resolve(__dirname,'../自检记录/坐姿左眼修正-20261027');fs.mkdirSync(out,{recursive:true});const r=await fetch(url);assert(r.ok);const raw=await r.text(),p=JSON.parse(raw),before=JSON.parse(raw);fs.writeFileSync(path.join(out,'before.json'),raw);const layer=p.layers.find(l=>l.sheetIndex===10&&l.name.startsWith('眼睛 /')),source=p.layers.find(l=>l.sheetIndex===8&&l.name===layer.name),decode=f=>png.decode(Buffer.from(f.dataURL.split(',')[1],'base64')),src=decode(source.frameData['8_0_0']);let changed=0;
for(let fi=0;fi<4;fi++){const k=`10_0_${fi}`,im=decode(layer.frameData[k]),points=[];for(let y=0;y<32;y++)for(let x=0;x<32;x++)if(im.data[(y*32+x)*4+3])points.push([x,y]);assert(points.length);const left=Math.min(...points.map(v=>v[0])),top=Math.min(...points.map(v=>v[1]));assert.equal(left,16);const data=new Uint8Array(im.data.length);for(let y=0;y<5;y++)for(let x=0;x<5;x++)data.set(src.data.subarray(((14+y)*32+12+x)*4,((14+y)*32+12+x)*4+4),((top+y)*32+left+x)*4);assert.notDeepEqual(data,im.data);for(let y=0;y<5;y++)for(let x=0;x<5;x++)assert.deepEqual(data.subarray(((top+y)*32+left+x)*4,((top+y)*32+left+x)*4+4),src.data.subarray(((14+y)*32+12+x)*4,((14+y)*32+12+x)*4+4));layer.frameData[k].dataURL='data:image/png;base64,'+png.encode(32,32,data).toString('base64');changed++;}
const eyeIndex=p.layers.indexOf(layer);for(let i=0;i<p.layers.length;i++){if(i!==eyeIndex)assert.deepEqual(p.layers[i],before.layers[i]);else for(const [k,v]of Object.entries(before.layers[i].frameData))if(!/^10_0_[0-3]$/.test(k))assert.deepEqual(layer.frameData[k],v);}assert.equal(changed,4);fs.writeFileSync(path.join(out,'candidate.json'),JSON.stringify(p));const save=await fetch(url,{method:'PUT',headers:{'Content-Type':'application/json','X-Pixel-Editor':'1','If-Match':r.headers.get('etag')},body:JSON.stringify(p)});assert(save.ok,'Save conflict '+save.status);assert.deepEqual(await(await fetch(url)).json(),p);console.log('Correct left-eye pixels in all four profile frames; all other layers and directions unchanged; API readback verified.');})().catch(e=>{console.error(e);process.exitCode=1;});
